9	/**
10	 * A fixed-capacity, generic {@link java.util.Deque} backed by a circular (ring)
11	 * buffer.
12	 *
13	 * <p>Elements can be inserted, removed, and examined at both ends in O(1) time.
14	 * The backing array is allocated once at construction and reused; the
15	 * {@code front} index and {@code size} are advanced modulo the capacity so the
16	 * common end operations never shift elements. (Arbitrary-element removal does
17	 * shift, in O(n), as in {@link java.util.ArrayDeque}.)
18	 *
19	 * <p>As a {@code Deque} this class is a superset of a FIFO queue and a LIFO
20	 * stack. The two operation styles behave as the interface specifies:
21	 * <ul>
22	 *   <li>{@code offer*} / {@code poll*} / {@code peek*} report failure by
23	 *       returning {@code false}/{@code null} (capacity-safe).</li>
24	 *   <li>{@code add*} / {@code remove*} / {@code get*} report failure by throwing
25	 *       {@link IllegalStateException} (full) or {@link NoSuchElementException}
26	 *       (empty).</li>
27	 * </ul>
28	 *
29	 * <p><strong>Null elements are not permitted.</strong> The contract uses
30	 * {@code null} as the sentinel returned by {@code poll}/{@code peek} for an
31	 * empty deque, so insertion methods throw {@link NullPointerException} for a
32	 * null argument, consistent with {@link java.util.ArrayDeque}.
33	 *
34	 * <p>The {@link #iterator()} and {@link #descendingIterator()} are fail-fast and
35	 * support {@link Iterator#remove()}, so the optional bulk operations
36	 * ({@code removeAll}, {@code retainAll}, {@code removeIf}) work as well.
37	 *
38	 * <p>This class is not thread-safe. External synchronization is required if
39	 * instances are accessed concurrently.
40	 *
41	 * @param <E> the type of elements held in this deque
42	 */
43	public class CircularQueue<E> extends AbstractQueue<E> implements Deque<E> {
44	
45	    private final Object[] elements;
46	    private int front;
47	    private int size;
48	
49	    /** Tracks structural modifications so iterators can fail fast. */
50	    private int modCount;
51	
52	    /**
53	     * Creates an empty deque able to hold up to {@code capacity} elements.
54	     *
55	     * @param capacity the maximum number of elements; must be positive
56	     * @throws IllegalArgumentException if {@code capacity <= 0}
57	     */
58	    public CircularQueue(int capacity) {
59	        if (capacity <= 0) {
60	            throw new IllegalArgumentException("capacity must be positive, was " + capacity);
61	        }
62	        this.elements = new Object[capacity];
63	        this.front = 0;
64	        this.size = 0;
65	    }
66	
67	    /** Returns the number of elements currently in the deque. */
68	    @Override
69	    public int size() {
70	        return size;
71	    }
72	
73	    /** Returns the maximum number of elements the deque can hold. */
74	    public int capacity() {
75	        return elements.length;
76	    }
77	
78	    /** Returns {@code true} if the deque cannot hold any more elements. */
79	    public boolean isFull() {
80	        return size == elements.length;
81	    }
82	
83	    // --- insertion --------------------------------------------------------
84	
85	    /**
86	     * Inserts the element at the front if space is available.
87	     *
88	     * @return {@code true} if added, {@code false} if the deque is full
89	     * @throws NullPointerException if {@code element} is null
90	     */
91	    @Override
92	    public boolean offerFirst(E element) {
93	        Objects.requireNonNull(element, "null elements are not permitted");
94	        if (isFull()) {
95	            return false;
96	        }
97	        front = (front - 1 + elements.length) % elements.length;
98	        elements[front] = element;
99	        size++;
100	        modCount++;
101	        return true;
102	    }
103	
104	    /**
105	     * Inserts the element at the rear if space is available.
106	     *
107	     * @return {@code true} if added, {@code false} if the deque is full
108	     * @throws NullPointerException if {@code element} is null
109	     */
110	    @Override
111	    public boolean offerLast(E element) {
112	        Objects.requireNonNull(element, "null elements are not permitted");
113	        if (isFull()) {
114	            return false;
115	        }
116	        elements[(front + size) % elements.length] = element;
117	        size++;
118	        modCount++;
119	        return true;
120	    }
121	
122	    /** Inserts the element at the front, or throws if the deque is full. */
123	    @Override
124	    public void addFirst(E element) {
125	        if (!offerFirst(element)) {
126	            throw new IllegalStateException("Deque is full (capacity " + elements.length + ")");
127	        }
128	    }
129	
130	    /** Inserts the element at the rear, or throws if the deque is full. */
131	    @Override
132	    public void addLast(E element) {
133	        if (!offerLast(element)) {
134	            throw new IllegalStateException("Deque is full (capacity " + elements.length + ")");
135	        }
136	    }
137	
138	    /** {@inheritDoc} Equivalent to {@link #offerLast(Object)}. */
139	    @Override
140	    public boolean offer(E element) {
141	        return offerLast(element);
142	    }
143	
144	    // --- removal ----------------------------------------------------------
145	
146	    /**
147	     * Removes and returns the front element.
148	     *
149	     * @return the former front element, or {@code null} if the deque is empty
150	     */
151	    @Override
152	    public E pollFirst() {
153	        if (isEmpty()) {
154	            return null;
155	        }
156	        E element = elementAt(front);
157	        elements[front] = null; // let the removed element be garbage collected
158	        front = (front + 1) % elements.length;
159	        size--;
160	        modCount++;
161	        return element;
162	    }
163	
164	    /**
165	     * Removes and returns the rear element.
166	     *
167	     * @return the former rear element, or {@code null} if the deque is empty
168	     */
169	    @Override
170	    public E pollLast() {
171	        if (isEmpty()) {
172	            return null;
173	        }
174	        int rear = (front + size - 1) % elements.length;
175	        E element = elementAt(rear);
176	        elements[rear] = null;
177	        size--;
178	        modCount++;
179	        return element;
180	    }
181	
182	    /** Removes and returns the front element, or throws if empty. */
183	    @Override
184	    public E removeFirst() {
185	        return nonNullOrThrow(pollFirst());
186	    }
187	
188	    /** Removes and returns the rear element, or throws if empty. */
189	    @Override
190	    public E removeLast() {
191	        return nonNullOrThrow(pollLast());
192	    }
193	
194	    /** {@inheritDoc} Equivalent to {@link #pollFirst()}. */
195	    @Override
196	    public E poll() {
197	        return pollFirst();
198	    }
199	
200	    // --- examination ------------------------------------------------------
201	
202	    /**
203	     * Returns, without removing, the front element.
204	     *
205	     * @return the front element, or {@code null} if the deque is empty
206	     */
207	    @Override
208	    public E peekFirst() {
209	        return isEmpty() ? null : elementAt(front);
210	    }
211	
212	    /**
213	     * Returns, without removing, the rear element.
214	     *
215	     * @return the rear element, or {@code null} if the deque is empty
216	     */
217	    @Override
218	    public E peekLast() {
219	        return isEmpty() ? null : elementAt((front + size - 1) % elements.length);
220	    }
221	
222	    /** Returns the front element, or throws if empty. */
223	    @Override
224	    public E getFirst() {
225	        return nonNullOrThrow(peekFirst());
226	    }
227	
228	    /** Returns the rear element, or throws if empty. */
229	    @Override
230	    public E getLast() {
231	        return nonNullOrThrow(peekLast());
232	    }
233	
234	    /** {@inheritDoc} Equivalent to {@link #peekFirst()}. */
235	    @Override
236	    public E peek() {
237	        return peekFirst();
238	    }
239	
240	    // --- stack view -------------------------------------------------------
241	
242	    /** {@inheritDoc} Equivalent to {@link #addFirst(Object)}. */
243	    @Override
244	    public void push(E element) {
245	        addFirst(element);
246	    }
247	
248	    /** {@inheritDoc} Equivalent to {@link #removeFirst()}. */
249	    @Override
250	    public E pop() {
251	        return removeFirst();
252	    }
253	
254	    // --- queue aliases (domain vocabulary) --------------------------------
255	
256	    /**
257	     * Convenience alias for {@link #addLast(Object)}.
258	     *
259	     * @throws IllegalStateException if the deque is full
260	     * @throws NullPointerException if {@code element} is null
261	     */
262	    public void enqueue(E element) {
263	        addLast(element);
264	    }
265	
266	    /**
267	     * Convenience alias for {@link #removeFirst()}.
268	     *
269	     * @throws NoSuchElementException if the deque is empty
270	     */
271	    public E dequeue() {
272	        return removeFirst();
273	    }
274	
275	    // --- occurrence removal ----------------------------------------------
276	
277	    /** {@inheritDoc} Removes the first (front-most) element equal to {@code o}. */
278	    @Override
279	    public boolean removeFirstOccurrence(Object o) {
280	        for (int i = 0; i < size; i++) {
281	            if (Objects.equals(o, getLogical(i))) {
282	                deleteAtLogical(i);
283	                return true;
284	            }
285	        }
286	        return false;
287	    }
288	
289	    /** {@inheritDoc} Removes the last (rear-most) element equal to {@code o}. */
290	    @Override
291	    public boolean removeLastOccurrence(Object o) {
292	        for (int i = size - 1; i >= 0; i--) {
293	            if (Objects.equals(o, getLogical(i))) {
294	                deleteAtLogical(i);
295	                return true;
296	            }
297	        }
298	        return false;
299	    }
300	
301	    /** {@inheritDoc} Equivalent to {@link #removeFirstOccurrence(Object)}. */
302	    @Override
303	    public boolean remove(Object o) {
304	        return removeFirstOccurrence(o);
305	    }
306	
307	    /** Removes all elements, leaving the deque empty but with unchanged capacity. */
308	    @Override
309	    public void clear() {
310	        Arrays.fill(elements, null);
311	        front = 0;
312	        size = 0;
313	        modCount++;
314	    }
315	
316	    // --- iteration --------------------------------------------------------
317	
318	    /**
319	     * Returns a fail-fast iterator over the elements from front to rear.
320	     * Supports {@link Iterator#remove()}.
321	     */
322	    @Override
323	    public Iterator<E> iterator() {
324	        return new AscendingIterator();
325	    }
326	
327	    /**
328	     * Returns a fail-fast iterator over the elements from rear to front.
329	     * Supports {@link Iterator#remove()}.
330	     */
331	    @Override
332	    public Iterator<E> descendingIterator() {
333	        return new DescendingIterator();
334	    }
335	
336	    private final class AscendingIterator implements Iterator<E> {
337	        private int cursor = 0;
338	        private int lastReturned = -1;
339	        private int expectedModCount = modCount;
340	
341	        @Override
342	        public boolean hasNext() {
343	            return cursor < size;
344	        }
345	
346	        @Override
347	        public E next() {
348	            checkForComodification();
349	            if (cursor >= size) {
350	                throw new NoSuchElementException();
351	            }
352	            lastReturned = cursor;
353	            E element = getLogical(cursor);
354	            cursor++;
355	            return element;
356	        }
357	
358	        @Override
359	        public void remove() {
360	            if (lastReturned < 0) {
361	                throw new IllegalStateException("next() has not been called, or remove() already called");
362	            }
363	            checkForComodification();
364	            deleteAtLogical(lastReturned);
365	            // Remaining elements shifted down into the gap; resume from the gap.
366	            cursor = lastReturned;
367	            lastReturned = -1;
368	            expectedModCount = modCount;
369	        }
370	
371	        private void checkForComodification() {
372	            if (modCount != expectedModCount) {
373	                throw new ConcurrentModificationException();
374	            }
375	        }
376	    }
377	
378	    private final class DescendingIterator implements Iterator<E> {
379	        private int cursor = size - 1;
380	        private int lastReturned = -1;
381	        private int expectedModCount = modCount;
382	
383	        @Override
384	        public boolean hasNext() {
385	            return cursor >= 0;
386	        }
387	
388	        @Override
389	        public E next() {
390	            checkForComodification();
391	            if (cursor < 0) {
392	                throw new NoSuchElementException();
393	            }
394	            lastReturned = cursor;
395	            E element = getLogical(cursor);
396	            cursor--;
397	            return element;
398	        }
399	
400	        @Override
401	        public void remove() {
402	            if (lastReturned < 0) {
403	                throw new IllegalStateException("next() has not been called, or remove() already called");
404	            }
405	            checkForComodification();
406	            deleteAtLogical(lastReturned);
407	            // Only elements after the gap shift; those still to visit (below the
408	            // cursor) keep their logical indices, so the cursor is unchanged.
409	            lastReturned = -1;
410	            expectedModCount = modCount;
411	        }
412	
413	        private void checkForComodification() {
414	            if (modCount != expectedModCount) {
415	                throw new ConcurrentModificationException();
416	            }
417	        }
418	    }
419	
420	    // --- internals --------------------------------------------------------
421	
422	    /** Returns the element at logical position {@code i} (0 == front). */
423	    private E getLogical(int i) {
424	        return elementAt((front + i) % elements.length);
425	    }
426	
427	    /** Sets the element at logical position {@code i} (0 == front). */
428	    private void setLogical(int i, E value) {
429	        elements[(front + i) % elements.length] = value;
430	    }
431	
432	    /**
433	     * Removes the element at logical position {@code k}, closing the gap by
434	     * shifting whichever side is smaller, and advances {@code front} when the
435	     * head side moves. Order of the remaining elements is preserved.
436	     */
437	    private void deleteAtLogical(int k) {
438	        if (k < size - 1 - k) {
439	            // Closer to the front: slide logical [0..k-1] up into [1..k].
440	            for (int i = k; i > 0; i--) {
441	                setLogical(i, getLogical(i - 1));
442	            }
443	            setLogical(0, null);
444	            front = (front + 1) % elements.length;
445	        } else {
446	            // Closer to the rear: slide logical [k+1..size-1] down into [k..size-2].
447	            for (int i = k; i < size - 1; i++) {
448	                setLogical(i, getLogical(i + 1));
449	            }
450	            setLogical(size - 1, null);
451	        }
452	        size--;
453	        modCount++;
454	    }
455	
456	    @SuppressWarnings("unchecked")
457	    private E elementAt(int index) {
458	        return (E) elements[index];
459	    }
460	
461	    private E nonNullOrThrow(E element) {
462	        if (element == null) {
463	            throw new NoSuchElementException("Deque is empty");
464	        }
465	        return element;
466	    }
467	
468	    // --- value equality (extension beyond the Collection contract) --------
469	
470	    /**
471	     * Compares deques by logical contents and order, front to rear. Two deques
472	     * are equal if they hold equal elements in the same order, regardless of
473	     * capacity or internal buffer alignment.
474	     *
475	     * <p>This is an intentional value-equality extension beyond the
476	     * {@code Collection} contract (which leaves {@code equals} as identity for
477	     * deques); it only ever considers another {@code CircularQueue} equal.
478	     */
479	    @Override
480	    public boolean equals(Object o) {
481	        if (this == o) {
482	            return true;
483	        }
484	        if (!(o instanceof CircularQueue<?> other)) {
485	            return false;
486	        }
487	        if (size != other.size) {
488	            return false;
489	        }
490	        Iterator<E> a = iterator();
491	        Iterator<?> b = other.iterator();
492	        while (a.hasNext()) {
493	            if (!Objects.equals(a.next(), b.next())) {
494	                return false;
495	            }
496	        }
497	        return true;
498	    }
499	
500	    @Override
501	    public int hashCode() {
502	        int hash = 1;
503	        for (E element : this) {
504	            hash = 31 * hash + element.hashCode();
505	        }
506	        return hash;
507	    }
508	}
