    /** {@inheritDoc} Removes the first (front-most) element equal to {@code o}. */
    @Override
    public boolean removeFirstOccurrence(Object o) {
        for (int i = 0; i < size; i++) {
            if (Objects.equals(o, getLogical(i))) {
